const summary = $('GET catalog-api summary').first().json || {};
const byType = $('GET file-scanner by-type').first().json || {};

const lines = ['\uD83D\uDCE5 Download Catalog - Daily Digest'];

// Real shape from download_catalog.py's /api/analytics/summary:
// { by_category: [{category,total,imported,downloaded,downloading,total_bytes}],
//   by_status: [{status,count}], by_source: [{source_app,count}], research: {...} }
if (summary.error) lines.push('', '(catalog-api unreachable - catalog section skipped)');
if (byType.error) lines.push('', '(file-scanner unreachable - library section skipped)');
const byCategory = summary.by_category || [];
if (byCategory.length) {
  lines.push('', 'Catalog (by category):');
  for (const row of byCategory.slice(0, 20)) {
    const gb = row.total_bytes ? (row.total_bytes / 1e9).toFixed(1) : '0.0';
    lines.push(`  ${row.category}: ${row.total} total (${row.imported} imported, ${row.downloading} downloading), ${gb} GB`);
  }
}
const byStatus = summary.by_status || [];
if (byStatus.length) {
  lines.push('', 'By status:');
  for (const row of byStatus.slice(0, 20)) {
    lines.push(`  ${row.status}: ${row.count}`);
  }
}

const types = byType.by_type || [];
if (Array.isArray(types) && types.length) {
  lines.push('', 'Existing library (file-scanner, by type):');
  for (const row of types.slice(0, 20)) {
    const gb = row.total_gb ? Number(row.total_gb).toFixed(1) : '?';
    lines.push(`  ${row.file_type}: ${row.count} files, ${gb} GB, ${row.duplicates || 0} dupes`);
  }
}

const body = lines.join('\n');
return [{
  json: {
    txn_id: Date.now().toString(),
    matrixPayload: { msgtype: 'm.text', body },
  },
}];
